  IF refusal IS NOT NULL THEN
    RAISE EXCEPTION '%', refusal USING ERRCODE = '42501';
  END IF;
  INSERT INTO "_supatype"."realtime_outbox" (topic, event, payload, sender)
    VALUES (topic, event, payload, "_supatype".jwt_uid());
